        })
      })
    }
  }

  console.log('Checked ' + files.length + ' files: ' + errorCount + ' errors, ' + warningCount + ' warnings')
  if (errorCount > 0) process.exitCode = 1
}

main().catch(function (error) {
  console.error(error && error.stack ? error.stack : error)
  process.exitCode = 1
